def ety_side_json(side_key):
    if side_key[0] == "ACTIVE":
        return {
            "state": "ACTIVE",
            "digest": side_key[1],
            "at": side_key[2],
        }
    return {"state": "EMPTY", "digest": None, "at": None}

def ety_source_sort_key(node_key):
    # EMPTY 先于 ACTIVE；ACTIVE 再按 digest 的 UTF-8 字节序、
    # at 升序。
    if node_key[0] == "EMPTY":
        return (0,)
    return (
        1, node_key[1].encode("utf-8"), node_key[2]
    )

def ety_ordered_bfs(source_key, depth_limit):
    # etp 同款定序 BFS：邻接表各边 first 全局互异且按首次发
    # 生时刻升序，首次定父即最短跳数且 first 序列字典序最小
    # 的路径。返回命中 target 时的 (hops, 反向节点栈, 反向边
    # 栈)；不可达或超跳返回 None。
    parent = {source_key: None}
    frontier = [(source_key, 0)]
    head = 0
    hit_depth = None
    while head < len(frontier):
        node_key, node_depth = frontier[head]
        head += 1
        if hit_depth is not None and node_depth >= hit_depth:
            break
        if node_depth >= depth_limit:
            continue
        for next_key, edge_key in adjacency.get(node_key, ()):
            if next_key not in parent:
                parent[next_key] = (node_key, edge_key)
                frontier.append((next_key, node_depth + 1))
                if (
                    next_key == target_key
                    and hit_depth is None
                ):
                    hit_depth = node_depth + 1
    if hit_depth is None:
        return None
    reversed_nodes = []
    reversed_edges = []
    current = target_key
    while current != source_key:
        previous_node, edge_key = parent[current]
        reversed_nodes.append(current)
        reversed_edges.append(edge_key)
        current = previous_node
    reversed_nodes.append(source_key)
    return hit_depth, reversed_nodes, reversed_edges

